#include <stdio.h>
#include <string.h>

#define MAX_FLAGS 20

typedef struct { char name[32]; int enabled; } Flag;

Flag flags[MAX_FLAGS];
int flag_count = 0;

void ff_set(char *name, int val) {
    for (int i = 0; i < flag_count; i++) {
        if (strcmp(flags[i].name, name) == 0) { flags[i].enabled = val; return; }
    }
    if (flag_count < MAX_FLAGS) {
        strcpy(flags[flag_count].name, name);
        flags[flag_count].enabled = val;
        flag_count++;
    }
}

int ff_get(char *name) {
    for (int i = 0; i < flag_count; i++)
        if (strcmp(flags[i].name, name) == 0) return flags[i].enabled;
    return 0;
}

void ff_list() {
    for (int i = 0; i < flag_count; i++)
        printf("%s: %s\n", flags[i].name, flags[i].enabled ? "ON" : "OFF");
}

int main() {
    ff_set("dark_mode", 1);
    ff_set("beta_api", 0);
    ff_set("debug_logs", 1);
    printf("dark_mode: %s\n", ff_get("dark_mode") ? "ON" : "OFF");
    printf("beta_api: %s\n", ff_get("beta_api") ? "ON" : "OFF");
    printf("All flags:\n");
    ff_list();
    return 0;
}
